--
-- 系统运行状态表 ( 2026-09 新增 : Web 控制台 ( k-spider-web ) 的跨进程状态与指令通道 ;
-- 主程序上报 / 消费 , k-spider-web 读取展示与写入指令 , 老库由启动时 Pg.EnsureSystemDbObjects 幂等补齐 )
--

-- 任务调度态 : 每节点每任务一行 ( upsert 不膨胀 ) ; 执行列由 JobRuntimeListener 写 , 调度列由 NodeStateJob 刷新
CREATE TABLE IF NOT EXISTS "public"."spider_job_state" (
  "node_id" text NOT NULL,
  "job_name" text NOT NULL,
  "next_fire_time" timestamp without time zone,
  "is_paused" boolean NOT NULL DEFAULT false,
  "last_fired_at" timestamp without time zone,
  "last_duration_ms" bigint,
  "last_success" boolean,
  "consecutive_failures" integer NOT NULL DEFAULT 0,
  "last_error" text,
  "last_stats" text,
  "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "spider_job_state_pkey" PRIMARY KEY ("node_id", "job_name")
);

COMMENT ON TABLE "public"."spider_job_state" IS '任务调度态 ( 执行结果 + 调度列 , 控制台展示 )';
COMMENT ON COLUMN "public"."spider_job_state"."last_stats" IS '上次执行摘要 ( 如 新增列表 12 )';

-- 任务指令 : k-spider-web 写 pending , 爬虫节点由 NodeStateJob 轮询消费后回写 done / rejected
CREATE TABLE IF NOT EXISTS "public"."spider_job_command" (
  "id" bigserial NOT NULL,
  "node_id" text,
  "job_name" text NOT NULL,
  "action" text NOT NULL,
  "status" text NOT NULL DEFAULT 'pending',
  "result" text,
  "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "consumed_at" timestamp without time zone,
  CONSTRAINT "spider_job_command_pkey" PRIMARY KEY ("id")
);

COMMENT ON TABLE "public"."spider_job_command" IS '任务指令 ( trigger / pause / resume , Web → 爬虫 的控制通道 )';
COMMENT ON COLUMN "public"."spider_job_command"."node_id" IS '目标节点 , 空 = 任意节点 ( 分布式时的路由依据 )';

-- 指令轮询热路径 : 只扫 pending ( NodeStateJob 每 3 秒 )
CREATE INDEX IF NOT EXISTS "idx_job_command_pending"
  ON "public"."spider_job_command" ("id") WHERE status = 'pending';

-- 节点状态快照 : NewsCheckJob 每轮 upsert ( 接口探测 / 管线积压 / 快讯滞后 / 验证冷却 )
CREATE TABLE IF NOT EXISTS "public"."spider_node_status" (
  "node_id" text NOT NULL,
  "report_time" timestamp without time zone NOT NULL,
  "payload" text,
  "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "spider_node_status_pkey" PRIMARY KEY ("node_id")
);

COMMENT ON TABLE "public"."spider_node_status" IS '节点状态快照 ( payload 为 JSON 文本 , report_time 过远即节点失联 )';

CREATE TRIGGER update_modified_column BEFORE UPDATE ON spider_job_state FOR EACH ROW EXECUTE FUNCTION update_time_func();

CREATE TRIGGER update_modified_column BEFORE UPDATE ON spider_job_command FOR EACH ROW EXECUTE FUNCTION update_time_func();

CREATE TRIGGER update_modified_column BEFORE UPDATE ON spider_node_status FOR EACH ROW EXECUTE FUNCTION update_time_func();

-- 数据集 ( 2026-10 新增第七管线 : loot-drop.io 倒闭创业公司案例库 , Supabase REST 全量拉取 ,
-- 行会修订 —— content_hash 变更检测 upsert ) ; 数据集型管线首源 , 每源一表 ( spider_<源>_<实体> )
CREATE TABLE IF NOT EXISTS "public"."spider_lootdrop_startup" (
  "id" bigint NOT NULL,
  "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "from_media" integer NOT NULL,
  "name" varchar(300) NOT NULL,
  "description" text,
  "sector" varchar(100),
  "country" varchar(100),
  "founders" text,
  "investors" text,
  "start_year" integer,
  "end_year" integer,
  "total_funding" bigint,
  "difficulty" smallint,
  "difficulty_reason" text,
  "scalability" smallint,
  "scalability_reason" text,
  "market_potential" varchar(16),
  "market_potential_reason" text,
  "cause_of_death" text,
  "the_loot" text,
  "market_analysis" text,
  "pivot_idea" text,
  "source_created_at" timestamp without time zone,
  "status" varchar(32),
  "primary_cause_of_death" varchar(100),
  "product_type" varchar(100),
  "views" integer,
  "condensed_value_prop" text,
  "condensed_cause_of_death" text,
  "content_hash" varchar(64) NOT NULL,
  "raw_content" text,
  CONSTRAINT "spider_lootdrop_startup_pkey" PRIMARY KEY ("id")
);

COMMENT ON TABLE "public"."spider_lootdrop_startup" IS '数据集 ( loot-drop.io 案例库 , 有界集合行可修订 , content_hash 变更检测 )';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."id" IS '源侧主键 ( API startups.id , 直接沿用非自增 )';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."total_funding" IS '累计融资额 ( 美元 )';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."founders" IS '创始人 JSON 数组文本';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."investors" IS '投资机构 JSON 数组文本';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."the_loot" IS '失败教训清单 JSON 数组文本';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."pivot_idea" IS '重建构想 JSON 对象文本';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."source_created_at" IS '源侧创建时间 ( UTC 去时区 )';
COMMENT ON COLUMN "public"."spider_lootdrop_startup"."content_hash" IS '全部业务字段 SHA256 指纹 ( upsert 变更检测依据 , 哈希没变的行不 UPDATE )';

CREATE INDEX IF NOT EXISTS "idx_lootdrop_startup_sector"
  ON "public"."spider_lootdrop_startup" ("sector");

CREATE TRIGGER update_modified_column BEFORE UPDATE ON spider_lootdrop_startup FOR EACH ROW EXECUTE FUNCTION update_time_func();

