COMMENT ON COLUMN "public"."spider_lootdrop_startup_zh"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."spider_lootdrop_startup_zh"."update_time" IS '最后修改时间 ( update_time_func 触发器自动刷新 )';
