COMMENT ON COLUMN "public"."spider_lootdrop_startup_zh"."market_potential_reason" IS '市场潜力档位理由 ( 中文译文 )';
COMMENT ON COLUMN "public"."spider_lootdrop_startup_zh"."cause_of_death" IS '死因分析 ( 中文译文 )';
